/**
 * SENTINEL glossary — the single source for every acronym, abbreviation and jargon term shown in the UI.
 * Each entry: plain-English meaning (1 sentence), why it matters on this dashboard, optional authoritative link.
 * `match` lists the exact on-screen spellings that get a dotted underline + tooltip automatically (see <AutoTerms>).
 * Explanations deliberately avoid introducing new acronyms.
 */
export type GlossCat = 'Vulnerabilities' | 'Attacks & malware' | 'Internet & networks' | 'Crypto' | 'Statistics' | 'Sources' | 'This dashboard';
export interface Gloss { id: string; term: string; full?: string; cat: GlossCat; meaning: string; why: string; link?: string; match?: string[] }

export const GLOSSARY: Gloss[] = [
  // ---------------- Vulnerabilities
  { id: 'vulnerability', term: 'Vulnerability', cat: 'Vulnerabilities', meaning: 'A flaw in software or hardware that an attacker could use to do something they should not be able to do.', why: 'Most break-ins start by abusing a known flaw, so new and exploited flaws are an early warning of where attacks will come from.', link: 'https://csrc.nist.gov/glossary/term/vulnerability', match: ['vulnerability', 'vulnerabilities', 'vulns'] },
  { id: 'cve', term: 'CVE', full: 'Common Vulnerabilities and Exposures', cat: 'Vulnerabilities', meaning: 'The public ID number given to a specific security flaw, written like CVE-2026-12345.', why: 'It lets everyone — vendors, insurers, security teams — talk about exactly the same flaw. Counts of new ones show how much patching work is piling up.', link: 'https://www.cve.org/About/Overview', match: ['CVE', 'CVEs'] },
  { id: 'cvss', term: 'CVSS', full: 'Common Vulnerability Scoring System', cat: 'Vulnerabilities', meaning: 'A 0–10 score for how bad a flaw would be if used: 9.0+ is Critical, 7.0+ High, 4.0+ Medium, below that Low.', why: 'It measures potential damage, not likelihood — a 9.8 that nobody is using may matter less than a 7.5 that is being actively exploited.', link: 'https://www.first.org/cvss/', match: ['CVSS', 'CVSS v4'] },
  { id: 'epss', term: 'EPSS', full: 'Exploit Prediction Scoring System', cat: 'Vulnerabilities', meaning: 'A daily, data-driven estimate of the chance a flaw will be used in real attacks within the next 30 days.', why: 'It complements the severity score with likelihood. Here, 10% or more is treated as "hot" — most flaws score well under 1%.', link: 'https://www.first.org/epss/', match: ['EPSS'] },
  { id: 'kev', term: 'KEV', full: 'Known Exploited Vulnerabilities catalogue', cat: 'Vulnerabilities', meaning: 'The United States cyber-defence agency\'s official list of flaws it has confirmed are being used by attackers in the wild.', why: 'This is the strongest "patch this now" signal available publicly. Additions mean real attacks, not theory.', link: 'https://www.cisa.gov/known-exploited-vulnerabilities-catalog', match: ['KEV', 'CISA KEV', 'Known exploited vulns'] },
  { id: 'kevdue', term: 'Due date (KEV)', cat: 'Vulnerabilities', meaning: 'The deadline by which United States federal agencies must fix a flaw after it is added to the exploited list.', why: 'Short deadlines signal the agency considers the flaw especially urgent; private organisations often use the same dates as a benchmark.', link: 'https://www.cisa.gov/known-exploited-vulnerabilities', match: ['due'] },
  { id: 'nvd', term: 'NVD', full: 'National Vulnerability Database', cat: 'Sources', meaning: 'The United States government\'s public database of security flaws, run by the national standards institute, which adds severity scores and details to each new ID.', why: 'It is the main source for "how many serious new flaws appeared". It has an analysis backlog, so the most recent weeks are always under-counted.', link: 'https://nvd.nist.gov/', match: ['NVD', 'NVD critical', 'NVD CVEs'] },
  { id: 'euvd', term: 'EUVD', full: 'European Union Vulnerability Database', cat: 'Sources', meaning: 'The European Union\'s own public database of security flaws, run by its cybersecurity agency.', why: 'A second, European view of new and exploited flaws, useful where the United States database lags.', link: 'https://euvd.enisa.europa.eu/', match: ['EUVD', 'ENISA EUVD'] },
  { id: 'enisa', term: 'ENISA', full: 'European Union Agency for Cybersecurity', cat: 'Sources', meaning: 'The European Union\'s cybersecurity agency.', why: 'It publishes the European vulnerability database shown in the vulnerabilities panel.', link: 'https://www.enisa.europa.eu/', match: ['ENISA'] },
  { id: 'cisa', term: 'CISA', full: 'Cybersecurity and Infrastructure Security Agency', cat: 'Sources', meaning: 'The United States government agency responsible for national cyber defence and critical-infrastructure security.', why: 'It runs the exploited-flaws catalogue and publishes advisories that often lead the news.', link: 'https://www.cisa.gov/about', match: ['CISA', 'CISA Advisories'] },
  { id: 'cwe', term: 'CWE', full: 'Common Weakness Enumeration', cat: 'Vulnerabilities', meaning: 'A catalogue of types of coding mistake (for example "SQL injection" or "buffer overflow"), each with an ID like CWE-79.', why: 'It tells you what kind of mistake caused a flaw, which hints at how it would be attacked.', link: 'https://cwe.mitre.org/about/index.html', match: ['CWE'] },
  { id: 'zeroday', term: 'Zero-day', cat: 'Vulnerabilities', meaning: 'A flaw that attackers are using before the maker has released a fix — defenders have had "zero days" to patch.', why: 'These are the most dangerous flaws because patching alone cannot stop them yet.', link: 'https://csrc.nist.gov/glossary/term/zero_day_attack', match: ['zero-day', 'Zero-day', '0-day'] },
  { id: 'exploit', term: 'Exploit / exploited', cat: 'Vulnerabilities', meaning: 'An exploit is the method or code that uses a flaw; "exploited" means attackers are actually doing it.', why: 'The gap between "a flaw exists" and "it is being exploited" is the gap between theoretical and real risk.', match: ['exploited', 'Exploited', 'exploitation'] },
  { id: 'patch', term: 'Patch', cat: 'Vulnerabilities', meaning: 'A software update from the maker that fixes a flaw.', why: 'Most exploited flaws already have a patch; incidents often come from organisations that have not applied it.', match: ['patch', 'patched'] },
  { id: 'vendor', term: 'Vendor / product', cat: 'Vulnerabilities', meaning: 'The company that makes the affected software or device, and the specific product.', why: 'Filtering by vendor shows whether a supplier your organisation relies on is seeing a run of serious flaws.', match: ['Vendor', 'vendors'] },
  { id: 'backlog', term: 'Analysis backlog', cat: 'Sources', meaning: 'The queue of new flaws the national database has not yet reviewed and scored.', why: 'Unscored flaws do not show up as Critical or High yet, so recent counts look lower than they will once reviewed.', link: 'https://nvd.nist.gov/general/news', match: ['backlog'] },

  // ---------------- Attacks & malware
  { id: 'ransomware', term: 'Ransomware', cat: 'Attacks & malware', meaning: 'Criminal software that locks or steals an organisation\'s data and demands payment to unlock it or not publish it.', why: 'It is the most financially damaging common attack for businesses and the largest driver of cyber-insurance claims.', link: 'https://www.cisa.gov/stopransomware', match: ['ransomware', 'Ransomware'] },
  { id: 'leaksite', term: 'Leak site', cat: 'Attacks & malware', meaning: 'A website run by a ransomware gang where it names victims who have not paid, and threatens to publish their stolen data.', why: 'Leak-site posts are the main public count of ransomware victims — but they are the criminals\' own claims, unverified, posted days to weeks after the break-in, and victims who pay quietly never appear.', link: 'https://www.ransomware.live/about', match: ['leak-site', 'leak site', 'Leak-site'] },
  { id: 'claim', term: 'Claim (ransomware)', cat: 'Attacks & malware', meaning: 'A victim name posted by a ransomware gang on its leak site.', why: 'Treat each as an allegation: some are exaggerated, recycled or fake. Trends in claims are still a useful gauge of gang activity.', match: ['claims', 'claimed'] },
  { id: 'rwgroup', term: 'Ransomware group', cat: 'Attacks & malware', meaning: 'A criminal operation (often a "brand" such as Akira or Qilin) that runs ransomware attacks and a leak site, frequently renting its tools to affiliates.', why: 'A single group surging can drive the whole trend; groups also rebrand, so names come and go.', match: ['group', 'groups'] },
  { id: 'malware', term: 'Malware', cat: 'Attacks & malware', meaning: 'Any software built to harm, spy on or take control of a computer.', why: 'Tracking which malware families are active shows what kind of attacks are circulating right now.', link: 'https://csrc.nist.gov/glossary/term/malware', match: ['malware', 'Malware', 'Malware families'] },
  { id: 'botnet', term: 'Botnet', cat: 'Attacks & malware', meaning: 'A network of infected computers secretly controlled by criminals and used together — to send spam, steal data, or deliver ransomware.', why: 'Botnets are a common first step before a ransomware attack, so active botnet servers are an early-warning signal.', link: 'https://csrc.nist.gov/glossary/term/botnet', match: ['botnet', 'Botnet'] },
  { id: 'c2', term: 'C2', full: 'Command and control', cat: 'Attacks & malware', meaning: 'The server criminals use to send instructions to, and collect stolen data from, infected computers.', why: 'Each live server represents an active criminal operation; taking them down disrupts attacks, so the online count rises and falls with police action.', link: 'https://attack.mitre.org/tactics/TA0011/', match: ['C2', 'C2 servers', 'C2 online', 'Botnet C2'] },
  { id: 'ioc', term: 'IOC', full: 'Indicator of compromise', cat: 'Attacks & malware', meaning: 'A clue that a system has been attacked — such as a known-bad internet address, web address or file fingerprint.', why: 'Security teams load these into their defences to block or detect known attacks.', link: 'https://csrc.nist.gov/glossary/term/indicator_of_compromise', match: ['IOC', 'IOCs'] },
  { id: 'ttp', term: 'TTP', full: 'Tactics, techniques and procedures', cat: 'Attacks & malware', meaning: 'How an attacker typically operates — their habits and methods from break-in to payout.', why: 'Methods change more slowly than addresses or files, so they are a more durable way to recognise a threat.', link: 'https://csrc.nist.gov/glossary/term/tactics_techniques_and_procedures', match: ['TTP', 'TTPs'] },
  { id: 'emotet', term: 'Emotet', cat: 'Attacks & malware', meaning: 'A long-running criminal malware family spread by email that rents out access to infected computers to other gangs.', why: 'Historically a common route into networks before ransomware. Its servers appear in the botnet tracker.', link: 'https://www.cisa.gov/news-events/cybersecurity-advisories/aa20-280a', match: ['Emotet'] },
  { id: 'qakbot', term: 'QakBot (QBot)', cat: 'Attacks & malware', meaning: 'A banking-theft malware family that became a major delivery route for ransomware until a 2023 police takedown.', why: 'Any return of its servers would be a meaningful warning sign.', link: 'https://www.justice.gov/opa/pr/qakbot-malware-disrupted-international-cyber-takedown', match: ['QakBot', 'Qakbot', 'QBot'] },
  { id: 'malfam', term: 'Dridex, TrickBot, Pikabot, Heodo…', cat: 'Attacks & malware', meaning: 'Names of other criminal malware families tracked by the botnet tracker; Heodo is the tracker\'s internal name for Emotet.', why: 'Seeing a family come back online after a takedown is a signal worth noting.', link: 'https://feodotracker.abuse.ch/', match: ['Dridex', 'TrickBot', 'Pikabot', 'Heodo', 'BumbleBee', 'IcedID'] },
  { id: 'phishing', term: 'Phishing', cat: 'Attacks & malware', meaning: 'Tricking people — usually by email, text or a fake website — into handing over passwords, money or access.', why: 'Still the most common way attacks begin, for businesses and crypto users alike.', link: 'https://www.cisa.gov/secure-our-world/recognize-and-report-phishing', match: ['phishing', 'Phishing'] },
  { id: 'supplychain', term: 'Supply-chain attack', cat: 'Attacks & malware', meaning: 'Attacking a supplier (software, service or website component) to reach its many customers at once.', why: 'One breach can create many simultaneous victims — a classic accumulation risk for insurers.', link: 'https://www.cisa.gov/topics/information-communications-technology-supply-chain-security', match: ['supply chain', 'supply-chain'] },
  { id: 'attribution', term: 'Attribution', cat: 'Attacks & malware', meaning: 'Saying who carried out an attack — a specific gang or a country.', why: 'It is hard and often contested; this dashboard never attributes attacks itself and only repeats what sources say.', match: ['attribution', 'Attribution'] },
  { id: 'lazarus', term: 'Lazarus / DPRK', cat: 'Attacks & malware', meaning: 'Lazarus is a hacking group widely linked to North Korea (officially the Democratic People\'s Republic of Korea), blamed for many of the largest crypto thefts.', why: 'Much of the biggest crypto losses are attributed to state-backed groups, which is why stolen funds are rarely recovered.', link: 'https://www.fbi.gov/news/press-releases/fbi-statement-on-attribution-of-malicious-cyber-activity-posed-by-the-democratic-peoples-republic-of-korea', match: ['Lazarus', 'DPRK'] },
  { id: 'critinfra', term: 'Critical infrastructure', cat: 'Attacks & malware', meaning: 'Services society depends on — healthcare, energy, water, transport, finance, government, communications.', why: 'Attacks here cause outsized harm and attract government response, so they are coloured red in the sector breakdown.', link: 'https://www.cisa.gov/topics/critical-infrastructure-security-and-resilience', match: ['critical-infrastructure', 'critical infrastructure'] },
  { id: 'sector', term: 'Sector', cat: 'Attacks & malware', meaning: 'The industry of the victim organisation (for example manufacturing, healthcare, technology), as classified by the ransomware tracker.', why: 'Shows which industries are being hit — directly relevant for underwriting and portfolio exposure.', match: ['sector', 'sectors', 'Sectors'] },

  // ---------------- Internet & networks
  { id: 'ip', term: 'IP address', full: 'Internet Protocol address', cat: 'Internet & networks', meaning: 'The numeric address of a device on the internet, like 203.0.113.7.', why: 'Attack sources and criminal servers are listed by address; addresses can be rented, shared or hijacked, so they identify a machine, not a person.', link: 'https://en.wikipedia.org/wiki/IP_address', match: ['IP'] },
  { id: 'port', term: 'Port', cat: 'Internet & networks', meaning: 'A numbered "door" on an internet-connected device; each service listens on one (web on 443, remote login on 22, and so on).', why: 'The most-probed ports show which kinds of exposed services attackers are hunting for today.', link: 'https://en.wikipedia.org/wiki/Port_(computer_networking)', match: ['port', 'ports', 'Targeted ports', 'Top attacked port'] },
  { id: 'ssh', term: 'SSH (port 22)', full: 'Secure Shell', cat: 'Internet & networks', meaning: 'The standard way administrators log in to servers remotely over the internet.', why: 'Constantly targeted with password-guessing; an exposed login with a weak password is a common way in.', link: 'https://en.wikipedia.org/wiki/Secure_Shell', match: ['SSH', 'SSH-alt'] },
  { id: 'telnet', term: 'Telnet (port 23)', cat: 'Internet & networks', meaning: 'An old, unencrypted remote-login method still found on cheap routers, cameras and other devices.', why: 'Heavily scanned by botnets that recruit insecure devices; seeing it near the top is normal background noise.', link: 'https://en.wikipedia.org/wiki/Mirai_(malware)', match: ['Telnet'] },
  { id: 'rdp', term: 'RDP (port 3389)', full: 'Remote Desktop Protocol', cat: 'Internet & networks', meaning: 'Microsoft\'s tool for controlling a Windows computer remotely.', why: 'Exposed remote desktops are one of the most common ways ransomware gangs break in.', link: 'https://en.wikipedia.org/wiki/Remote_Desktop_Protocol', match: ['RDP'] },
  { id: 'smb', term: 'SMB (port 445)', full: 'Server Message Block', cat: 'Internet & networks', meaning: 'Windows file-sharing; it should never be open to the internet.', why: 'Behind famous outbreaks such as WannaCry; scanning for it is a sign of worms and ransomware looking for easy targets.', link: 'https://learn.microsoft.com/en-us/windows-server/storage/file-server/file-server-smb-overview', match: ['SMB'] },
  { id: 'web', term: 'HTTP / HTTPS (ports 80 / 443)', cat: 'Internet & networks', meaning: 'The protocols used to load websites; the "S" version is encrypted.', why: 'Web servers and web-facing appliances are scanned constantly for flaws.', link: 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview', match: ['HTTP', 'HTTPS', 'HTTP-alt', 'HTTPS-alt'] },
  { id: 'dbports', term: 'Database & service ports', cat: 'Internet & networks', meaning: 'Names like MySQL, MSSQL, Postgres, Redis, MongoDB, Elastic and Memcached are databases or data stores; ADB is Android\'s debugging bridge; VNC is screen-sharing; FTP, SMTP, DNS, NTP, SNMP, SIP, UPnP, PPTP and TR-069 are older internet services for files, email, names, time, device management, phone calls, home-router setup and remote access.', why: 'If any of these is reachable from the internet it is usually a mistake — attackers scan for them to steal data or take over devices.', link: 'https://www.cisa.gov/cyber-hygiene-services', match: ['MySQL', 'MSSQL', 'Postgres', 'Redis', 'MongoDB', 'Elastic', 'Memcached', 'ADB', 'VNC', 'FTP', 'SMTP', 'DNS', 'NTP', 'SNMP', 'SIP', 'UPnP', 'PPTP', 'TR-069'] },
  { id: 'ics', term: 'Industrial control protocols', cat: 'Internet & networks', meaning: 'Modbus, S7comm, BACnet and DNP3 are languages used by factory machines, building systems and utilities.', why: 'These should almost never face the internet; scanning for them hints at interest in physical systems, so they are highlighted red.', link: 'https://www.cisa.gov/topics/industrial-control-systems', match: ['Modbus', 'S7comm', 'BACnet', 'DNP3'] },
  { id: 'tcp', term: 'tcp', cat: 'Internet & networks', meaning: 'The basic internet connection method most services use; shown when a port has no well-known name.', why: 'Just a placeholder label — the number is what matters.', match: ['tcp'] },
  { id: 'asn', term: 'AS / ASN', full: 'Autonomous System (number)', cat: 'Internet & networks', meaning: 'A block of internet addresses run by one organisation, such as an internet provider, cloud company or hosting firm, identified by a number.', why: 'Tells you whose network an attack came from — often a cloud or hosting provider rather than the attacker\'s home.', link: 'https://en.wikipedia.org/wiki/Autonomous_system_(Internet)', match: ['AS', 'ASN', 'AS cc', 'autonomous system', 'Network'] },
  { id: 'ascountry', term: 'AS registration country', cat: 'Internet & networks', meaning: 'The country where the network that owns an internet address is registered.', why: 'It is not where the attacker is: criminals route through rented servers worldwide, so "top attacking country" mainly reflects where cheap servers are.', link: 'https://en.wikipedia.org/wiki/Autonomous_system_(Internet)', match: ['registration country', 'AS registration country'] },
  { id: 'cc', term: 'Country code', cat: 'Internet & networks', meaning: 'Two-letter country abbreviation (US = United States, DE = Germany, CN = China, "??" = unknown).', why: 'Used on the map and tables to keep labels compact; hover a country on the map for its full name.', link: 'https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2', match: ['cc'] },
  { id: 'sensor', term: 'Sensor (DShield)', cat: 'Internet & networks', meaning: 'A volunteer\'s firewall or trap machine that reports unwanted connection attempts it sees.', why: 'Counts depend on how many volunteers are reporting, so they show the level of background scanning, not actual incidents.', link: 'https://www.dshield.org/howto.html', match: ['sensor', 'sensors', 'Sensor trend', 'sensor reports'] },
  { id: 'scanning', term: 'Scanning', cat: 'Internet & networks', meaning: 'Automated probing of every internet address to find open doors or vulnerable services.', why: 'It is constant background noise; spikes on a particular port often follow a newly announced flaw.', match: ['scanning'] },
  { id: 'cert', term: 'CERT / CSIRT', full: 'Computer Emergency Response Team / Computer Security Incident Response Team', cat: 'Sources', meaning: 'A national (or sector) team that warns about attacks and software flaws and helps victims respond — e.g. JPCERT/CC (Japan), CERT-FR (France), CERT-Bund (Germany), KrCERT (Korea), HKCERT (Hong Kong).', why: 'Their advisories in the news feed are the most authoritative signal for their country.', match: ['CERT', 'CSIRT'] },
  { id: 'cluster', term: 'Grouped incident ("N sources")', cat: 'This dashboard', meaning: 'Several reports of the same event from different outlets, merged into one row with a timeline.', why: 'Stops one big incident looking like many, and shows how the story developed. Grouping is rule-based (shared names / title words within 7 days), so occasionally it can merge or miss.', match: ['N sources'] },
  { id: 'rss', term: 'RSS feed', cat: 'Sources', meaning: 'A standard machine-readable list of a website\'s latest articles.', why: 'The news panel is built from the feeds of security news sites and government advisories.', match: ['RSS'] },

  // ---------------- Sources
  { id: 'dshield', term: 'DShield', cat: 'Sources', meaning: 'A free community project that collects firewall logs from thousands of volunteers to measure internet-wide attack traffic.', why: 'Powers the "top attacked ports" and attack-source views.', link: 'https://www.dshield.org/', match: ['DShield'] },
  { id: 'isc', term: 'SANS ISC', full: 'SANS Internet Storm Center', cat: 'Sources', meaning: 'A long-running volunteer early-warning service run by the SANS security training institute; it operates DShield.', why: 'Its handlers publish the daily diary in the news feed and set the Infocon level.', link: 'https://isc.sans.edu/', match: ['ISC', 'SANS ISC', 'SANS ISC Diary', 'SANS Internet Storm Center', 'SANS'] },
  { id: 'infocon', term: 'Infocon', cat: 'Sources', meaning: 'The Internet Storm Center\'s overall internet threat level: green (normal), yellow, orange or red (severe, widespread disruption).', why: 'It is almost always green; anything else means its handlers see an unusual, internet-wide event.', link: 'https://isc.sans.edu/infocon.html', match: ['Infocon', 'ISC Infocon'] },
  { id: 'feodo', term: 'Feodo Tracker', cat: 'Sources', meaning: 'A free list, run by the Swiss non-profit abuse.ch, of live criminal botnet servers.', why: 'Source of the botnet server counts.', link: 'https://feodotracker.abuse.ch/', match: ['Feodo Tracker', 'Feodo'] },
  { id: 'threatfox', term: 'ThreatFox', cat: 'Sources', meaning: 'abuse.ch\'s shared database of attack clues (bad addresses, web addresses, file fingerprints).', why: 'Shown as offline here because it now requires a free access key, which has not been configured.', link: 'https://threatfox.abuse.ch/', match: ['ThreatFox'] },
  { id: 'rwlive', term: 'ransomware.live', cat: 'Sources', meaning: 'An independent site that monitors ransomware leak sites and logs each victim claim.', why: 'Source of all ransomware numbers here; its coverage has grown over time, which inflates long-run growth.', link: 'https://www.ransomware.live/', match: ['ransomware.live'] },
  { id: 'defillama', term: 'DeFiLlama', cat: 'Sources', meaning: 'A widely used public data site for decentralised finance; it keeps a dataset of crypto hacks and losses.', why: 'Source of every crypto incident and dollar figure on the Crypto tab.', link: 'https://defillama.com/hacks', match: ['DeFiLlama', 'DeFiLlama hacks dataset'] },
  { id: 'firstorg', term: 'FIRST', full: 'Forum of Incident Response and Security Teams', cat: 'Sources', meaning: 'The global association of security response teams; it maintains the severity score and the exploit-likelihood score.', why: 'Owner of two of the scores used on the vulnerability list.', link: 'https://www.first.org/about/', match: ['FIRST'] },
  { id: 'ncsc', term: 'NCSC', full: 'National Cyber Security Centre (UK)', cat: 'Sources', meaning: 'The United Kingdom\'s national cybersecurity authority.', why: 'One of the government advisory feeds in the news panel.', link: 'https://www.ncsc.gov.uk/', match: ['NCSC', 'UK NCSC'] },
  { id: 'acsc', term: 'ACSC', full: 'Australian Cyber Security Centre', cat: 'Sources', meaning: 'Australia\'s national cybersecurity agency, part of the Australian Signals Directorate (cyber.gov.au).', why: 'Its alerts are in the news feed — the most locally relevant government source for Australian readers.', link: 'https://en.wikipedia.org/wiki/Australian_Cyber_Security_Centre', match: ['ACSC'] },

  // ---------------- Crypto
  { id: 'defi', term: 'DeFi', full: 'Decentralised finance', cat: 'Crypto', meaning: 'Financial services (lending, trading, savings) run by computer programs on a blockchain instead of by a company.', why: 'Most crypto hacks hit these services, because a bug in the code can be used to drain the money it holds.', link: 'https://www.investopedia.com/decentralized-finance-defi-5113835', match: ['DeFi', 'DeFi Protocol'] },
  { id: 'cefi', term: 'CeFi', full: 'Centralised finance', cat: 'Crypto', meaning: 'Crypto businesses run by a company that holds customers\' funds — mainly exchanges.', why: 'Breaches here are usually stolen passwords or keys rather than code bugs, and tend to be very large.', link: 'https://www.investopedia.com/tech/what-are-centralized-cryptocurrency-exchanges/', match: ['CeFi', 'CeFi (exchange)', 'CEX'] },
  { id: 'blockchain', term: 'Blockchain / chain', cat: 'Crypto', meaning: 'A shared public ledger of transactions maintained by many computers; each separate network (Ethereum, Solana…) is a "chain".', why: '"By chain" shows which networks are losing the most money to attacks.', link: 'https://en.wikipedia.org/wiki/Blockchain', match: ['chain', 'chains', 'Chain', 'blockchain'] },
  { id: 'l1', term: 'Layer 1 / L1', cat: 'Crypto', meaning: 'A base blockchain network itself (such as Bitcoin, Ethereum or Solana), as opposed to apps or add-on networks built on top.', why: 'Attacks on the base network are rare but can affect everyone using it.', link: 'https://ethereum.org/en/developers/docs/scaling/', match: ['L1', 'Chain / L1', 'Layer 1'] },
  { id: 'l2', term: 'Layer 2 networks', cat: 'Crypto', meaning: 'Arbitrum, Optimism, Base, Blast, Linea and zkSync are add-on networks that process Ethereum transactions more cheaply and settle back to it.', why: 'They hold large sums and are linked to Ethereum by bridges, a frequent hacking target.', link: 'https://ethereum.org/en/layer-2/', match: ['Arbitrum', 'Optimism', 'Base', 'Blast', 'Linea', 'zkSync Era', 'zkSync'] },
  { id: 'chains', term: 'Major chains', cat: 'Crypto', meaning: 'Ethereum, Solana, Bitcoin, Tron, Avalanche, Polygon, Fantom, Sui and others are separate blockchain networks; BSC / BNB Chain is the network run by the Binance exchange.', why: 'Losses cluster on the networks with the most money and apps, so big networks top the list by default.', link: 'https://en.wikipedia.org/wiki/Blockchain', match: ['Ethereum', 'BSC', 'BNB Chain', 'Binance Smart Chain', 'Solana', 'Bitcoin', 'Polygon', 'Avalanche', 'Tron', 'Fantom', 'Sui'] },
  { id: 'smartcontract', term: 'Smart contract', cat: 'Crypto', meaning: 'A program stored on a blockchain that automatically moves money according to its code.', why: 'if the code has a bug, attackers can take the funds and there is usually no undo.', link: 'https://ethereum.org/en/smart-contracts/', match: ['smart contract', 'smart contracts'] },
  { id: 'bridge', term: 'Bridge', cat: 'Crypto', meaning: 'A service that moves crypto between two different blockchains by locking it on one and issuing an equivalent on the other.', why: 'Bridges hold huge pooled balances, so they have suffered some of the largest hacks ever.', link: 'https://ethereum.org/en/bridges/', match: ['Bridge', 'bridge', 'Bridge exploit'] },
  { id: 'flashloan', term: 'Flash loan', cat: 'Crypto', meaning: 'An uncollateralised loan that is borrowed and repaid within a single transaction — seconds — so it can be enormous.', why: 'Attackers use them to borrow vast sums briefly to distort prices or exploit a bug, then repay the loan and keep the profit.', link: 'https://en.wikipedia.org/wiki/Flash_loan', match: ['Flash loan', 'flash loan'] },
  { id: 'oracle', term: 'Oracle / price manipulation', cat: 'Crypto', meaning: 'An oracle feeds outside information (like a token\'s price) to a smart contract; manipulation means tricking it with a fake price.', why: 'A contract that believes a fake price can be made to lend or pay out far too much.', link: 'https://ethereum.org/en/developers/docs/oracles/', match: ['Oracle / price manipulation', 'oracle', 'Oracle Manipulation'] },
  { id: 'reentrancy', term: 'Reentrancy', cat: 'Crypto', meaning: 'A coding bug where an attacker\'s program calls back into a contract before it finishes updating balances, letting them withdraw repeatedly.', why: 'A classic, well-understood bug that still recurs — a sign of weak code review.', link: 'https://ethereum.org/en/developers/docs/smart-contracts/security/', match: ['Reentrancy', 'reentrancy'] },
  { id: 'rugpull', term: 'Rug pull', cat: 'Crypto', meaning: 'When the people behind a crypto project run off with investors\' money.', why: 'It is insider fraud rather than an outside hack; common in small, new projects.', link: 'https://ethereum.org/en/security/', match: ['Rug pull', 'Rug pull / insider', 'Rugpull', 'rug pull'] },
  { id: 'drainer', term: 'Drainer', cat: 'Crypto', meaning: 'A scam toolkit that tricks a user into approving a transaction which then empties their crypto wallet.', why: 'A fast-growing form of phishing aimed at individuals; losses per victim are small but victims are many.', link: 'https://www.chainalysis.com/blog/crypto-drainers/', match: ['drainer', 'Phishing / drainer'] },
  { id: 'privkey', term: 'Private-key compromise', cat: 'Crypto', meaning: 'Theft of the secret code that controls a crypto wallet; whoever has the key can move the money.', why: 'Behind many of the largest losses, especially at exchanges; it is a classic security failure, not a code bug.', link: 'https://www.investopedia.com/terms/p/private-key.asp', match: ['Private-key compromise', 'private key', 'Key Compromise', 'Private Key Compromised', 'Hot Wallet Key Compromised'] },
  { id: 'hotwallet', term: 'Hot wallet', cat: 'Crypto', meaning: 'A crypto wallet that is kept online so funds can be moved quickly (versus "cold" storage kept offline).', why: 'Convenient but exposed — most exchange hacks drain hot wallets.', link: 'https://www.investopedia.com/hot-wallet-vs-cold-wallet-7098461', match: ['hot wallet', 'Hot Wallet'] },
  { id: 'wallet', term: 'Wallet', cat: 'Crypto', meaning: 'Software or a device that holds the keys to someone\'s crypto.', why: 'Wallet incidents are usually individuals or firms losing keys or being phished.', link: 'https://ethereum.org/en/wallets/', match: ['Wallet'] },
  { id: 'token', term: 'Token', cat: 'Crypto', meaning: 'A crypto asset issued by a project on top of a blockchain.', why: 'Token incidents are often bugs in how the token is created ("infinite mint") or insider dumping.', link: 'https://www.investopedia.com/terms/c/crypto-token.asp', match: ['Token'] },
  { id: 'accesscontrol', term: 'Access control flaw', cat: 'Crypto', meaning: 'A failure to restrict who can call sensitive functions — for example letting anyone withdraw or change settings.', why: 'The single most common technique in the hacks dataset; usually preventable with an audit.', link: 'https://ethereum.org/en/developers/docs/smart-contracts/security/', match: ['Access control', 'Access Control', 'Improper Access Control'] },
  { id: 'logicbug', term: 'Logic / accounting bug', cat: 'Crypto', meaning: 'A mistake in a contract\'s rules or arithmetic (for example rounding, share calculations, reward formulas) that lets someone take more than they should.', why: 'Grouped together here because they are all code-quality failures rather than stolen keys or scams.', match: ['Logic / accounting bug'] },
  { id: 'governance', term: 'Governance attack', cat: 'Crypto', meaning: 'Gaining enough voting power in a project (often with borrowed tokens) to pass a vote that sends its money to the attacker.', why: 'Exploits the project\'s own decision-making rules rather than a code bug.', link: 'https://ethereum.org/en/governance/', match: ['Governance attack', 'Governance'] },
  { id: 'marketmanip', term: 'Market manipulation', cat: 'Crypto', meaning: 'Artificially moving a token\'s price to profit at others\' expense.', why: 'Often combined with flash loans in crypto attacks.', link: 'https://www.investopedia.com/terms/m/manipulation.asp', match: ['Market manipulation'] },
  { id: 'frontend', term: 'Frontend / infra / supply chain', cat: 'Crypto', meaning: 'Attacks on a project\'s website, domain name, hosting or third-party code rather than its smart contracts — for example hijacking its web address to show a fake site.', why: 'The contracts can be perfect and users still lose money; it is ordinary web security.', match: ['Frontend / infra / supply chain', 'Frontend & Infrastructure', 'DNS Hijack'] },
  { id: 'nft', term: 'NFT', full: 'Non-fungible token', cat: 'Crypto', meaning: 'A unique digital collectible or ownership record on a blockchain.', why: 'NFT marketplaces and lending services appear as a small category of hacked targets.', link: 'https://www.investopedia.com/non-fungible-tokens-nft-5115211', match: ['NFT', 'NFTfi'] },
  { id: 'dao', term: 'DAO', full: 'Decentralised autonomous organisation', cat: 'Crypto', meaning: 'A crypto project run by token-holder votes instead of a management team.', why: 'Vulnerable to governance attacks.', link: 'https://ethereum.org/en/dao/', match: ['DAO'] },
  { id: 'web3', term: 'Web3', cat: 'Crypto', meaning: 'An umbrella term for blockchain-based apps and services.', why: 'Used as a keyword to match crypto-related flaws and news.', link: 'https://ethereum.org/en/web3/', match: ['web3', 'Web3'] },
  { id: 'solidity', term: 'Code language (Solidity, Rust, Move…)', cat: 'Crypto', meaning: 'The programming language the hacked smart contract was written in; Solidity is the main language for Ethereum-style chains.', why: 'Mostly reflects popularity — Solidity dominates because most money sits on those chains.', link: 'https://soliditylang.org/', match: ['Solidity', 'Code language'] },
  { id: 'usdtime', term: 'USD at time of hack', cat: 'Crypto', meaning: 'The dollar value of the stolen crypto on the day it was taken, as reported.', why: 'Crypto prices swing, so the same theft can look bigger or smaller later; figures here are not adjusted and not net of recoveries.', match: ['USD at time of hack', 'USD at the time of the hack', 'USD stolen', 'USD'] },
  { id: 'returned', term: 'Funds returned / recovered', cat: 'Crypto', meaning: 'Money given back by the attacker (sometimes for a "bounty") or frozen and recovered.', why: 'Recovery is rare and only recorded where the dataset has it, so the true figure may be a little higher.', match: ['Returned', 'Recovered', 'Funds returned'] },

  // ---------------- Statistics
  { id: 'trendtest', term: 'Mann–Kendall trend test', cat: 'Statistics', meaning: 'A standard statistical test that asks: across these periods, do values tend to go up (or down) more often than chance would produce?', why: 'It is how SENTINEL decides "Rising", "Falling" or "Stable" — it ignores single spikes and needs a consistent direction.', link: 'https://www.statisticshowto.com/mann-kendall-trend-test/', match: ['Mann–Kendall', 'Mann-Kendall', 'MK'] },
  { id: 'sen', term: 'Sen\'s slope', cat: 'Statistics', meaning: 'A robust estimate of how much a series changes per period, using the middle of all pairwise changes so outliers do not distort it.', why: 'Gives the size of a trend, while the trend test says whether it is real.', link: 'https://www.statisticshowto.com/sens-slope/', match: ["Sen's slope"] },
  { id: 'pvalue', term: 'p-value / p', cat: 'Statistics', meaning: 'The chance of seeing a change at least this big if nothing had really changed. Small (below 0.05) means "unlikely to be luck".', why: 'Marks which changes are real ("significant", shown with *) versus noise. It does not say how big or important the change is.', link: 'https://en.wikipedia.org/wiki/P-value', match: ['p-value', 'p <', 'p ='] },
  { id: 'significant', term: 'Significant / noise', cat: 'Statistics', meaning: '"Significant" means the change passed a statistical test (unlikely to be chance); "noise" means it could easily be random variation.', why: 'Stops you reacting to random wobble — most week-to-week movement in these numbers is noise.', link: 'https://www.investopedia.com/terms/s/statistically_significant.asp', match: ['significant', 'noise'] },
  { id: 'alpha', term: 'α (alpha) = 0.05', cat: 'Statistics', meaning: 'The cut-off for calling a result significant: a 5% chance of a false alarm is accepted.', why: 'With many things tested at once, about one in twenty "significant" results can still be chance.', link: 'https://en.wikipedia.org/wiki/Statistical_significance', match: ['α'] },
  { id: 'n', term: 'n', cat: 'Statistics', meaning: 'The number of data points (periods) a test used.', why: 'Smaller numbers make tests weaker; the dashboard needs at least 8 complete periods before calling a trend.', match: ['n='] },
  { id: 'mwu', term: 'Mann–Whitney U test', cat: 'Statistics', meaning: 'A test of whether one set of daily values tends to be higher than another, without assuming a bell-curve shape.', why: 'Used to decide whether "this period vs the last one" is a real difference.', link: 'https://www.statisticshowto.com/mann-whitney-u-test/', match: ['Mann–Whitney U', 'Mann-Whitney U'] },
  { id: 'poisson', term: 'Poisson test', cat: 'Statistics', meaning: 'A test for whether two counts of rare events (like 12 incidents vs 7) differ by more than chance.', why: 'Used for the "Top movers" table and crypto year-to-date comparisons.', link: 'https://www.statisticshowto.com/poisson-distribution/', match: ['Poisson', 'exact Poisson test', 'Exact Poisson'] },
  { id: 'sigma', term: 'σ (sigma) / z-score', cat: 'Statistics', meaning: 'Sigma is the standard deviation — the typical size of ups and downs; a z-score says how many of those a value is from normal.', why: 'A point more than 3σ above its trend is flagged as an anomaly — a genuinely unusual period.', link: 'https://www.investopedia.com/terms/z/zscore.asp', match: ['σ', 'z-score'] },
  { id: 'anomaly', term: 'Anomaly', cat: 'Statistics', meaning: 'A period far outside the usual range (here, more than 3σ above the expected level).', why: 'One-off spikes are worth a look, but are not the same as a sustained trend.', match: ['anomaly', 'Anomalies', 'anomalies'] },
  { id: 'ma', term: 'Moving average', cat: 'Statistics', meaning: 'The average of the last few periods, recalculated each period, to smooth out noise.', why: 'The smooth lines on the trend chart; easier to read direction than the jagged raw bars.', link: 'https://www.investopedia.com/terms/m/movingaverage.asp', match: ['moving average', 'MA'] },
  { id: 'yoy', term: 'YoY / vs last year', full: 'Year over year', cat: 'Statistics', meaning: 'Comparing a period with the same period a year earlier.', why: 'Removes seasonal effects (for example holiday lulls) that distort a simple "vs last month" comparison.', link: 'https://www.investopedia.com/terms/y/year-over-year.asp', match: ['YoY', 'vs last year'] },
  { id: 'ytd', term: 'YTD', full: 'Year to date', cat: 'Statistics', meaning: 'From 1 January this year until today.', why: 'Compared with the same stretch last year to see whether this year is worse.', link: 'https://www.investopedia.com/terms/y/ytd.asp', match: ['YTD', 'ytd', 'Year to date'] },
  { id: 'prior', term: 'vs prior window', cat: 'Statistics', meaning: 'Comparing the latest stretch (for example 30 days) with the stretch of the same length just before it.', why: 'Quick gauge of momentum, but sensitive to seasonality and one-off events — check the year-on-year figure too.', match: ['vs prior', 'prior window', 'prior 30d'] },
  { id: 'gran', term: 'Granularity (day / week / month)', cat: 'Statistics', meaning: 'How the timeline is grouped into buckets.', why: 'Longer buckets smooth noise and make trends clearer; daily buckets show spikes.', match: ['granularity'] },
  { id: 'lag', term: 'Reporting lag / partial period', cat: 'Statistics', meaning: 'The most recent days or the current week or month are incomplete because reports arrive late.', why: 'They always look artificially low, so they are hatched on charts and left out of tests.', match: ['reporting lag', 'reporting-lag', 'partial', 'Hatched'] },
  { id: 'heatmap', term: 'Calendar heatmap', cat: 'Statistics', meaning: 'A grid of days coloured from light to dark by how much activity each day had.', why: 'Shows weekly rhythms (weekends are quieter) and unusual bursts at a glance.', match: ['heatmap', 'Calendar heatmap'] },
  { id: 'sevindex', term: 'Severity index / mix', cat: 'Statistics', meaning: 'The share of events at each severity level over time, or a weighted total of them.', why: 'Answers "are things getting more serious", separately from "are there more of them".', match: ['Severity index', 'Severity mix', 'size mix'] },
  { id: 'combined', term: 'Combined incident index', cat: 'Statistics', meaning: 'Ransomware claims, exploited flaws and serious new flaws added together into one count.', why: 'A single headline gauge — but each part has its own caveats, so check the parts too.', match: ['Combined incident index', 'Combined'] },
  { id: 'movers', term: 'Risers / fallers (top movers)', cat: 'Statistics', meaning: 'The countries, sectors, groups or vendors whose counts changed most between the latest window and the one before.', why: 'Pinpoints what is driving an overall change; faint bars are changes that could be chance.', match: ['Top movers', 'Risers', 'Fallers'] },

  // ---------------- This dashboard
  { id: 'threatcon', term: 'THREATCON (SENTINEL)', cat: 'This dashboard', meaning: 'SENTINEL\'s own summary level from 1 (Low) to 5 (Severe) — 1 Low, 2 Guarded, 3 Elevated, 4 High, 5 Severe — blended from the live feeds; a higher number is always worse. It is not an official government level.', why: 'A quick "how busy is the threat picture today" gauge; hover it to see exactly which signals drive it.', match: ['THREATCON', 'Global THREATCON'] },
  { id: 'severity', term: 'Severity (critical / high / medium / low)', cat: 'This dashboard', meaning: 'SENTINEL\'s rule-based rating of each item, explained in its detail drawer (for example score 9.0+, exploited, ransomware-linked, or dollar size).', why: 'Helps you skim to what matters; it is a rule of thumb, not an expert judgement.', match: ['severity', 'Severity', 'High+ only'] },
  { id: 'live', term: 'Live / stale / offline', cat: 'This dashboard', meaning: 'Feed status: live = fresh data; stale = the last good copy is kept because a refresh is overdue or failed; offline = no data available at all.', why: 'SENTINEL never fills gaps with invented data — an offline feed simply shows nothing.', match: ['stale', 'offline', 'OFFLINE', 'feeds live', 'Feed offline', 'stale copy'] },
  { id: 'collector', term: 'Collector', cat: 'This dashboard', meaning: 'SENTINEL\'s server job that runs every minute and fetches each source on its own schedule (15 minutes to 6 hours).', why: '"Collected X ago" tells you how fresh the numbers are; refresh only re-reads the collector\'s latest copy.', match: ['collected', 'collector', 'Server collector'] },
  { id: 'heat', term: 'Activity heat (map)', cat: 'This dashboard', meaning: 'A per-country score: ransomware victims × 3 + online botnet servers × 2 + attack sources + news mentions.', why: 'A rough "where is activity" picture — attacker locations reflect where servers are registered, not who is behind them.', match: ['Activity heat'] },
  { id: 'utc', term: 'UTC', full: 'Coordinated Universal Time', cat: 'This dashboard', meaning: 'The world reference time (London winter time); Sydney is 10–11 hours ahead.', why: 'Sources date events in it, so days are grouped by it; your local time is shown alongside.', link: 'https://en.wikipedia.org/wiki/Coordinated_Universal_Time', match: ['UTC'] },
  { id: 'backfill', term: 'Backfill', cat: 'This dashboard', meaning: 'Gradually downloading past years of data in small, rate-limited slices.', why: 'Until the history is complete, very long-range vulnerability trends are partial.', match: ['backfill'] },
  { id: 'snapshot', term: 'Recorded snapshot', cat: 'This dashboard', meaning: 'For sources with no public history (news, botnet servers), SENTINEL saves one reading per day itself.', why: 'Those trends only start from when recording began and need at least 8 periods.', match: ['snapshot', 'snapshots', 'Recording'] },
];

export const GLOSS: Record<string, Gloss> = Object.fromEntries(GLOSSARY.map((g) => [g.id, g]));

/** Panel explainers: what the panel shows and how to read it (shown in the ⓘ popover and as Explain-mode captions). */
export const PANELS: Record<string, { what: string; read: string }> = {
  map: { what: 'Where activity is concentrated right now, coloured by a per-country score of ransomware victims, botnet servers, attack sources and news mentions.', read: 'Darker = more activity. Victim countries are where claimed victims are based; attacker countries are where the attacking servers are registered — not who is behind them. Click a country for its detail.' },
  ticker: { what: 'Every item from every feed, newest first, each with a severity rating.', read: 'Use "High+ only" to cut noise. Click an item to see exactly why it got its rating and a link to the original source.' },
  ransomware: { what: 'Victims named by ransomware gangs on their leak sites over the last 30 days: which gangs, which industries, which countries.', read: 'These are criminal claims, not confirmed incidents, and appear days to weeks after the break-in. Watch the shape of the curve and which sectors keep recurring rather than single days.' },
  vulns: { what: 'Security flaws that matter most: those confirmed as exploited (exploited list), newly published critical ones (United States database) and the European database.', read: 'Start with the exploited list — those are being used in real attacks. For the others, the severity score says how bad, the likelihood bar says how likely to be used soon.' },
  infra: { what: 'The machinery of attacks: which internet services are being probed most, which networks the probing comes from, which criminal botnet servers are online, and the daily volume of probing.', read: 'This is mostly constant background noise. The useful signals are changes: a new port jumping into the top list, or botnet servers coming back after a takedown.' },
  news: { what: 'Headlines from global security news sites, national CERTs / cyber agencies and regional outlets across every region, tagged with a rule-based severity and the countries involved. Reports of the same incident are grouped into one row ("N sources") with a timeline.', read: 'Use the source picker to focus on one outlet or agency. Government advisories are the most actionable; vendor and media stories add context. Open a grouped row to see how the story developed across sources.' },
  geoCoverage: { what: 'For each country: how many of our news sources are based there (live / total), how many items they published in the last 7 days, and how many incidents from any source were tied to that country.', read: 'Amber rows are gaps — no working local source, or nothing tied to the country this week. A gap means less visibility, not less risk. Sources marked ✕ were tried but publish no usable feed (hover for why).' },
  kpis: { what: 'Headline numbers for the selected time window, each with its own source.', read: 'Click a tile to filter the dashboard to that type of event. Small sparkline charts show the recent shape.' },
  trendsMain: { what: 'The selected series over time, with smoothed averages, the fitted trend line and flagged anomalies.', read: 'Focus on the trend line and the smoothed averages, not single bars. Hatched bars are incomplete periods and are ignored by the statistics.' },
  trendsStats: { what: 'A plain-language verdict on whether the selected series is rising, falling or stable, with the tests behind it.', read: '"Rising" requires a statistically consistent direction and at least a 5% change. Comparisons marked * are unlikely to be chance.' },
  verdicts: { what: 'One card per data series with its overall direction, and change versus the prior window and the same window last year.', read: 'Red arrow = statistically rising, green = falling, grey = no clear direction. * marks a change unlikely to be chance.' },
  sevmix: { what: 'How the mix of severity levels has shifted over time.', read: 'A growing red or orange share means incidents are getting more serious, even if the total count is flat.' },
  heatmap: { what: 'One square per day for the last 12 months, darker for busier days.', read: 'Look for runs of dark weeks (sustained campaigns) rather than single dark days.' },
  movers: { what: 'Which countries, industries, gangs or vendors changed most between the latest window and the one before.', read: 'Solid bars are statistically significant; faint bars could be chance. Click a row to filter the charts.' },
  coverage: { what: 'How far back each data series goes, any gaps, and the known biases of each source.', read: 'Read this before quoting a long-run trend — several sources have grown their coverage over time.' },
  cryptoStream: { what: 'Crypto hacks, crypto-related news, crypto-related software flaws and crypto-linked ransomware claims in one stream.', read: 'Toggle the item types at the top. Hack severity is based on dollar size; click any item for detail.' },
  cryptoStats: { what: 'Whether crypto losses and incident counts are statistically rising, plus this year vs last year.', read: 'Prefer the "Incidents ≥ $1M" series for direction — the all-sizes count is inflated by better recording of small incidents.' },
  cryptoTech: { what: 'Dollar losses grouped by how the attack worked, for the chosen window.', read: 'A few huge incidents dominate; check the count next to each bar to see whether a technique is common or just had one big hit.' },
  cryptoCat: { what: 'Dollar losses split by type of target: decentralised services, exchanges, bridges, wallets, base networks, tokens.', read: 'Exchange and bridge losses tend to be fewer but larger.' },
  cryptoChain: { what: 'Dollar losses by blockchain network.', read: 'Big networks top the list because they hold most of the money; incidents spanning several networks count in full toward each.' },
  cryptoTop: { what: 'The ten largest crypto incidents in the window.', read: 'These usually make up most of the total; one mega-hack can define a whole year.' },
  cryptoVulns: { what: 'Software flaws from the last 120 days whose descriptions mention crypto terms, or that are on the exploited list.', read: 'Keyword matching is approximate — open an item to check it really affects crypto software.' },
  cryptoSize: { what: 'The mix of incident sizes over time (under $1M, $1–10M, $10–100M, $100M+).', read: 'A growing share of large incidents is more worrying than more small ones.' },
};
